    public static void main(String[] args) {
        Rooms rooms = new Rooms();
        ReservationStore store = new ReservationStore();
        SentMessages messages = new SentMessages();
        PriceCalculator calc = new PriceCalculator();
        ReservationService service = new ReservationService(rooms, store, calc, new EmailSender(messages));

        // Reserva com crianças
        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
