            2, RatePlan.STANDARD, 2);

        Reservation reservation = service.create(request);
        service.confirm(reservation.id());
        ReservationReceipt receipt = service.receiptCopy(reservation.id());

        System.out.println("=== Comprovante com crianças ===");
        System.out.println(receipt.text());
        System.out.println();

        // Reserva sem crianças
        NewReservation request2 = new NewReservation(
            201, guest, 
            LocalDate.parse("2027-09-01"), 
            LocalDate.parse("2027-09-03"), 
            2, RatePlan.STANDARD, 0);

        Reservation reservation2 = service.create(request2);
        service.confirm(reservation2.id());
        ReservationReceipt receipt2 = service.receiptCopy(reservation2.id());

        System.out.println("=== Comprovante sem crianças ===");
        System.out.println(receipt2.text());
    }
}
